function dayDiff(a,b){const x=Date.parse(a+'T00:00:00Z'),y=Date.parse(b+'T00:00:00Z');return Number.isFinite(x)&&Number.isFinite(y)?Math.round((x-y)/86400000):0;}
function timing(r){const today=data?.hoy||'',presented=['Por revisar','Conforme'].includes(r.estado)&&r.presentacion,cut=r.estado==='Anulado'?(txt(r.ultimaOperacion).match(/^\d{4}-\d{2}-\d{2}/)?.[0]||today):presented?r.presentacion:today,delta=dayDiff(r.limite,cut),elapsed=Math.max(0,dayDiff(cut,r.inicio)),remaining=presented||r.estado==='Anulado'?0:Math.max(0,delta),excess=Math.max(0,-delta),condition=r.estado==='Anulado'?'Anulado':presented?(excess?'Presentado fuera del plazo':'Presentado dentro del plazo'):delta<0?'Vencido':delta===0?'Vence hoy':delta<=2?'Próximo a vencer':'Dentro del plazo';return {elapsed,remaining,excess,condition,plazo:Math.max(0,dayDiff(r.limite,r.inicio)),supervision:presented?Math.max(0,dayDiff(r.conformidad||today,r.presentacion)):0,delta,presented:!!presented};}
function hasKind(r,k){const t=timing(r),done=r.estado==='Conforme',work=!done&&r.estado!=='Por revisar';if(r.estado==='Anulado')return false;return k==='all'||k==='done'&&done||k==='pending'&&!done||k==='late'&&work&&t.excess>0||k==='review'&&r.estado==='Por revisar'||k==='within'&&work&&t.delta>2||k==='near'&&work&&t.delta>0&&t.delta<=2||k==='today'&&work&&t.delta===0||k==='timely'&&done&&t.excess===0||k==='delayed'&&done&&t.excess>0;}
