function consultStyles(){if($('hdi145Styles'))return;const style=document.createElement('style');style.id='hdi145Styles';style.textContent=`#hdi145Consult{position:fixed;inset:0;z-index:149;background:#09254bb0;display:flex;align-items:center;justify-content:center;padding:14px;box-sizing:border-box}#hdi145Consult .hdi145-dialog{width:min(96vw,1100px);max-height:94vh;max-height:94dvh;display:flex;flex-direction:column;background:#fff;border-radius:16px;overflow:hidden;color:#18365b;box-shadow:0 20px 60px #081a4750}#hdi145Consult header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 20px;background:#123570;color:white;flex:none}#hdi145Consult h2{font-size:21px;font-weight:800;margin:0}#hdi145Consult header span{font-size:13px;color:#d4e3fa}#hdi145Consult .hdi145-body{padding:16px;overflow:auto;min-height:0;display:grid;gap:12px;overscroll-behavior:contain}#hdi145Consult footer{display:flex;justify-content:flex-end;padding:12px 16px;border-top:1px solid #d2e0f3;flex:none}#hdi145Consult .hdi145-section{border:1px solid #d2e0f3;border-radius:10px;overflow:hidden;background:#fff}#hdi145Consult h4{background:#3377bf;color:white;padding:10px 14px;margin:0;font-size:14px;font-weight:750}#hdi145Consult .hdi145-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;padding:12px;margin:0}#hdi145Consult dt{color:#536d8e;font-size:12px;font-weight:650}#hdi145Consult dd{font-size:14px;margin:4px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}#hdi145Consult .hdi-table-wrap{margin:10px;max-height:none}#hdi145Consult .hdi-muted{padding:8px 12px}#hdi145Error:empty{display:none}#hdi145Error{color:#b91c1c;font-size:13px}#hdi145Consult .hdi-files{min-width:130px} @media(min-width:701px){#hdi145Consult .hdi145-body{display:flex;flex-direction:column;flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden}#hdi145Consult .hdi145-body>*{flex:0 0 auto;min-width:0}#hdi145Consult .hdi145-section{min-height:max-content}} @media(max-width:700px){#hdi145Consult{padding:7px}#hdi145Consult .hdi145-grid{grid-template-columns:repeat(2,minmax(0,1fr))}#hdi145Consult h2{font-size:17px}#hdi145Consult .hdi145-body{padding:8px}#hdi145Consult header{padding:12px}#hdi145Consult .hdi-table-wrap{overflow-x:auto}}`;document.head.appendChild(style);}

