function currentList(){if(!data)return [];if(activePage==='dash'){const f=filters.dash;return dashBase().filter(r=>(!f.person||r.responsable===f.person)&&(!f.detailPerson||r.responsable===f.detailPerson)&&hasKind(r,f.kind)&&(!f.stage||stage(r)===f.stage)&&search(r,f.q));}if(view==='derive'){const f=filters.derive;return data.disponibles.filter(r=>inPeriod(r.fechaRegistro,f)&&(!f.unit||unit(r)===f.unit)&&(!f.mode||mode(r)===f.mode)&&search(r,f.q,f.field));}if(view==='mine'){const f=filters.mine;return data.asignaciones.filter(r=>inPeriod(r.inicio,f)&&(data.admin||r.responsable===data.usuario)&&(f.kind==='cancel'?r.estado==='Anulado':hasKind(r,f.kind))&&(!f.stage||stage(r)===f.stage)&&search(r,f.q));}const f=filters.super;return data.asignaciones.filter(r=>inPeriod(r.inicio,f)&&(!f.person||r.responsable===f.person)&&(!f.state||r.estado===f.state)&&(!f.stage||stage(r)===f.stage)&&search(r,f.q));}
