 const options={amplInspDerive:[many?'Derivación masiva concluida satisfactoriamente.':'Expediente derivado satisfactoriamente.','No se pudo derivar el expediente.'],amplInspSave:['Avance de inspección guardado satisfactoriamente.','No se pudo guardar el avance de inspección.'],amplInspSubmit:['Inspección presentada satisfactoriamente para supervisión.','No se pudo presentar la inspección.'],amplInspUpload:[photo?'Fotografía adjuntada satisfactoriamente.':'Archivo adjuntado satisfactoriamente.',photo?'No se pudo adjuntar la fotografía.':'No se pudo adjuntar el archivo.'],amplInspDeleteAttach:['Archivo retirado satisfactoriamente.','No se pudo retirar el archivo.']};
