window.HDInspecciones={enter,reset,syncPermissions,allowed,admin,supervisor,canLeave:()=>{if(busy){message('Hay una operación de inspecciones en curso.');return false;}if(!guard())return false;closeConsult();closePreview();return true;}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind,{once:true});else bind();
